package com.singtel.redemptionservice;
import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.client.RestClient;import org.springframework.beans.factory.annotation.Value;import org.springframework.dao.DataIntegrityViolationException;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import java.security.Principal;import com.singtel.platformcommon.DomainError;
@RestController @RequestMapping("/api/v1/redemptions")public class RedemptionController{private final RedemptionRepository repo;private final RedemptionTransactions tx;private final RestClient client;private final String eligibilityUrl;public RedemptionController(RedemptionRepository r,RedemptionTransactions t,RestClient c,@Value("${platform.eligibility-url}")String u){repo=r;tx=t;client=c;eligibilityUrl=u;}
 public record Request(@NotNull UUID promotionId,@NotBlank @Size(max=64)String customerId){}
 @GetMapping @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public List<Redemption> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){if(page<0||size<1||size>100)throw new IllegalArgumentException();return repo.findAll(org.springframework.data.domain.PageRequest.of(page,size,org.springframework.data.domain.Sort.by("redeemedAt").descending())).getContent();}
 @GetMapping("/{id}") @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public Redemption get(@PathVariable UUID id){return repo.findById(id).orElseThrow(DomainError::missing);}
 @PostMapping @ResponseStatus(org.springframework.http.HttpStatus.CREATED) @PreAuthorize("hasAnyRole('MANAGER','ADMIN')")public Redemption redeem(@Valid @RequestBody Request input,@RequestHeader("Idempotency-Key")String key,Principal actor,HttpServletRequest req){if(!key.matches("[a-zA-Z0-9_-]{8,128}"))throw new IllegalArgumentException("Invalid idempotency key");var existing=repo.findByActorAndIdempotencyKey(actor.getName(),key);if(existing.isPresent())return tx.check(existing.get(),input.promotionId(),input.customerId());Map<String,Object> eligibility=client.get().uri(eligibilityUrl+"/api/v1/eligibility/"+input.customerId()+"/"+input.promotionId()).retrieve().body(Map.class);for(int attempt=0;attempt<3;attempt++){try{return tx.redeem(input.promotionId(),input.customerId(),key,actor.getName(),String.valueOf(req.getAttribute("correlationId")),eligibility);}catch(DataIntegrityViolationException e){if(attempt==2)throw e;}}throw new IllegalStateException();}
 @PostMapping("/{id}/cancel") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')")public Redemption cancel(@PathVariable UUID id){return tx.cancel(id);}
}
